"use client";
import { useRef, type CSSProperties, type PointerEvent } from "react";
import { ButtonSurface, buttonVariables, type AnimationButtonProps } from "./button-shared";
export interface MagneticButtonProps extends AnimationButtonProps {
  strength?: number;
  textStrength?: number;
  returnDuration?: number;
}
const css = `
.z-anb-magnetic{transform:translate(var(--z-anb-mx,0px),var(--z-anb-my,0px));transition:transform var(--z-anb-return,.65s) linear(0,.646 5%,1.25 10%,1.354 15%,1.125 20%,.912 25%,.875 30%,.956 35%,1.031 40%,1.044 45%,1.016 50%,.989 55%,.984 60%,.994 65%,1.004 70%,1.006 75%,1.002 80%,.999 85%,.998 90%,.999 95%,1),background-color .2s,color .2s}
.z-anb-magnetic .z-anb-label{transform:translate(var(--z-anb-tx,0px),var(--z-anb-ty,0px));transition:transform var(--z-anb-return,.65s) linear(0,.646 5%,1.25 10%,1.354 15%,1.125 20%,.912 25%,.875 30%,.956 35%,1.031 40%,1.044 45%,1.016 50%,.989 55%,.984 60%,.994 65%,1.004 70%,1.006 75%,1.002 80%,.999 85%,.998 90%,.999 95%,1)}
.z-anb-magnetic[data-active=true]{background:var(--z-anb-fill);transition:transform var(--z-anb-duration) var(--z-anb-easing),background-color .2s,color .2s}.z-anb-magnetic[data-active=true] .z-anb-label{transition:transform var(--z-anb-duration) var(--z-anb-easing)}
@media(prefers-reduced-motion:reduce),(hover:none){.z-anb-magnetic,.z-anb-magnetic .z-anb-label{transform:none!important}}
`;
/** Button and label follow the pointer by separate amounts, then spring home. */
export function MagneticButton({
  children = "Shop Now",
  strength = 0.16,
  textStrength = 0.22,
  duration = 1.6,
  returnDuration = 1.6,
  easing = "cubic-bezier(.22,1,.36,1)",
  background = "#ff5722",
  fill = "#e64a19",
  ...props
}: MagneticButtonProps) {
  const anchor = useRef({ x: 0, y: 0, width: 0, height: 0 });
  const track = (
    element: HTMLButtonElement | HTMLAnchorElement,
    event: PointerEvent<HTMLButtonElement | HTMLAnchorElement>,
  ) => {
    if (window.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches) return;
    const box = anchor.current;
    const x = Math.max(
      -box.width / 2,
      Math.min(box.width / 2, event.clientX - box.x - box.width / 2),
    );
    const y = Math.max(
      -box.height / 2,
      Math.min(box.height / 2, event.clientY - box.y - box.height / 2),
    );
    for (const [key, value] of [
      ["mx", x * strength],
      ["my", y * strength],
      ["tx", x * textStrength],
      ["ty", y * textStrength],
    ] as const)
      element.style.setProperty(`--z-anb-${key}`, `${value}px`);
  };
  return (
    <>
      <style>{css}</style>
      <ButtonSurface
        {...props}
        variant="magnetic"
        variables={
          {
            ...buttonVariables({ ...props, duration, easing, background, fill }),
            "--z-anb-return": `${Math.max(0, returnDuration)}s`,
          } as CSSProperties
        }
        onEngage={(element, event) => {
          // The geometry read below flushes CSS. Commit this phase first so
          // entry cannot accidentally start with the elastic release curve.
          element.dataset.active = "true";
          const box = element.getBoundingClientRect(),
            matrix = new DOMMatrix(getComputedStyle(element).transform);
          anchor.current = {
            x: box.x - matrix.m41,
            y: box.y - matrix.m42,
            width: box.width,
            height: box.height,
          };
          if (event) track(element, event);
        }}
        onTrack={track}
        onDisengage={(element) => {
          element.dataset.active = "false";
          for (const key of ["mx", "my", "tx", "ty"])
            element.style.setProperty(`--z-anb-${key}`, "0px");
        }}
      >
        <span className="z-anb-label">{children}</span>
      </ButtonSurface>
    </>
  );
}
